const SYNONYMS={dentista:'odonto odontopediatra odontopediatria',pediatra:'pediatria',escola:'colegio escolas',mecanico:'mecanica oficina',eletricista:'eletrica',diarista:'faxina limpeza',mudanca:'transportadora frete',berco:'berço',imovel:'apartamento casa imóveis',saude:'odontopediatria pediatra clinica',pets:'veterinario veterinaria',climatizacao:'ar condicionado split',carro:'mecanica oficina despachante',casa:'eletrica limpeza reparos',aula:'aulas reforco'};
function queryTerms(q){return norm(q).split(/[^a-z0-9]+/).filter(x=>x.length>1&&!['de','da','do','das','dos','em','no','na','para','com','um','uma','por','perto'].includes(x));}
function matches(q,text,keywords=[]){const terms=queryTerms(q);if(!terms.length)return true;const hay=norm(text+' '+keywords.join(' '));return terms.every(w=>hay.includes(w)||(SYNONYMS[w]||'').split(' ').some(s=>s&&hay.includes(norm(s))));}
function matchingBiz(q){return cityBiz().filter(b=>b.claimed!==false&&matches(q,b.name+' '+b.cat+' '+b.svc.join(' '),b.kw||[])).slice(0,3);}
function searchLists(){const q=searchQuery.trim();return {items:cityItems().filter(i=>i.status==='active'&&matches(q,i.title+' '+i.desc+' '+i.hood)),biz:cityBiz().filter(b=>matches(q,b.name+' '+b.cat+' '+b.svc.join(' ')+' '+b.hoods.join(' '),b.kw||[])),asks:cityAsks().filter(a=>matches(q,a.q+' '+a.topic,a.keywords||[])),groups:cityGroups().filter(g=>matches(q,g.t+' '+g.about)),events:state.events.filter(e=>e.city===state.city&&e.date>=dateISO()&&matches(q,e.title+' '+e.description+' '+e.place))};}
function renderSearch(){return `<div class="page-head"><div><h1>Buscar em ${esc(state.city)}</h1><p>Encontre oportunidades, negócios e respostas da comunidade.</p></div></div>${filterChips([['all','Tudo'],['items','Anúncios'],['biz','Negócios'],['asks','Indicações'],['groups','Grupos'],['events','Encontros']],searchType,'search-type')}<div id="search-results">${searchResults()}</div>`;}
function searchResults(){
 if(!searchQuery.trim())return `${searchStartSections()}${empty('Uma busca para toda a cidade','Digite um serviço, produto, bairro ou assunto.','search')}`;
 const groups=searchLists(),count=Object.entries(groups).filter(([k])=>searchType==='all'||searchType===k).reduce((n,[,v])=>n+v.length,0);
 if(!count)return `<section class="section">${empty('Nada sobre “'+searchQuery+'”','Tente termos mais simples. Se a dúvida ainda não tiver resposta, pergunte à comunidade.','search_off',readonly()?'':'ask-from-search',readonly()?'':'Pedir indicação')}</section>`;
 let h=`<p class="small muted" style="margin-top:18px">${count} ${count===1?'resultado':'resultados'} em ${esc(state.city)}</p>`;
 if(groups.items.length&&(searchType==='all'||searchType==='items'))h+=`<section class="section">${sectionTitle('Anúncios')}<div class="card-grid">${groups.items.map(photoCard).join('')}</div></section>`;
 if(groups.biz.length&&(searchType==='all'||searchType==='biz'))h+=`<section class="section">${sectionTitle('Negócios')}<div class="card-grid">${groups.biz.map(businessCard).join('')}</div></section>`;
 if(groups.asks.length&&(searchType==='all'||searchType==='asks'))h+=`<section class="section">${sectionTitle('Indicações e respostas')}<div class="list">${groups.asks.map(questionRow).join('')}</div></section>`;
 if(groups.groups.length&&(searchType==='all'||searchType==='groups'))h+=`<section class="section">${sectionTitle('Grupos')}<div class="list">${groups.groups.map(groupRow).join('')}</div></section>`;
 if(groups.events.length&&(searchType==='all'||searchType==='events'))h+=`<section class="section">${sectionTitle('Encontros')}<div class="list">${groups.events.map(eventRow).join('')}</div></section>`;return h;
}

// Rodada 10: histórico e sugestões em seções separadas. Antes, com uma busca no histórico,
// as sugestões sumiam; e sem histórico as sugestões apareciam rotuladas como "recentes".
function searchStartSections(){const chip=(x,ic)=>`<md-suggestion-chip label="${esc(x)}" data-action="recent-search" data-value="${esc(x)}">${icon(ic,'icon')}</md-suggestion-chip>`;const row=(title,items,ic)=>items.length?`<section class="section">${sectionTitle(title)}<div class="filter-row"><md-chip-set>${items.map(x=>chip(x,ic)).join('')}</md-chip-set></div></section>`:'';const suggestions=['escola','berço','mudança','mecânico'].filter(x=>!state.recent.some(r=>norm(r)===norm(x)));return row('Buscas recentes',state.recent,'history')+row('Sugestões',suggestions,'search');}